"""The grader's configuration: grader_config.json, generated by the maintainers' generator from the public entries of
the task's table of numbers. Read once, checked, and handed out as one flat mapping {key: value}.

    cfg = config.load(path)          # Config: cfg["hazard.voxel"], cfg.layout, cfg.runtime

No knob has a default anywhere in the grader: a key of VALUE_KEYS, LAYOUT_KEYS or RUNTIME_KEYS that is missing, a key
that is not on those lists, or a value of the wrong kind is a ConfigError (a task error, never a verdict on a twin).
One key is held by rule: key_frames.list (the scored moments by name) is in the file exactly when key_frames.named is
true (the first version's setting); when it is false (rule L of the second version) the file must not hold it and the
grader takes the scored moments from the truth's own hidden index (twin/truth.py).

grader_config.json:
    {"format": "flight-twin-grader-config/1",
     "values": {key: value, ...},            exactly VALUE_KEYS: the public entries of the table, as they are
     "pending_in_table": {key: {"value": v, "source": "..."}, ...},   exactly the numbers of GAP_KEYS that the table
                                             does not hold yet (the generator marks them; an empty object once it does)
     "layout": {...},                        where the truth, the reference and the grader's copies of the givens lie
     "runtime": {...},                       the verifier's own limits (worker account, address space, time plan;
                                             the ray stage's cap equals the value runtime.rays_time_limit_s,
                                             the scene stage's cap runtime.scene_time_limit_s and the worker's
                                             address-space limit runtime.scene_memory_limit_mb)
     "generated_from": {...}}                the generator's record (hashes of its sources); not read by the grader
"""
import json
import math

FORMAT = "flight-twin-grader-config/1"

# every entry of the table of numbers the grader reads (the generator copies exactly these public entries)
VALUE_KEYS = (
    "flights.count_first_version", "flights.names_neutral",
    "key_frames.per_flight", "key_frames.time_offset_wide_minus_depth_stamp",
    "wide_camera.body_mount_translation", "wide_camera.body_mount_quaternion_xyzw",
    "two_camera_transform.translation", "two_camera_transform.quaternion_xyzw",
    "depth_camera.image_size", "depth_camera.rays", "depth_camera.never_returning_corner_pixels",
    "depth_camera.ray_table_sha256",
    "depth.scored_range_min", "depth.scored_range_max", "depth.band_full_abs", "depth.band_full_rel",
    "depth.band_zero_factor", "depth.min_class_pixels_per_frame", "depth.weight_content",
    "depth.weight_structure_times_content",
    "hazard.voxel", "hazard.min_range", "hazard.max_range", "hazard.robot_radius", "hazard.collision_distance",
    "hazard.inflation_radius", "hazard.inflation_offsets", "hazard.path_sample", "hazard.move_start",
    "hazard.directions_azimuth", "hazard.directions_elevation", "hazard.lengths", "hazard.max_length",
    "hazard.stop_band_full", "hazard.stop_band_zero",
    "score.weight_hazard", "score.weight_depth", "score.anchor", "score.full_at", "score.flight_aggregation",
    "gate.one_flight.position_threshold", "gate.one_flight.angle_threshold", "gate.one_flight.scale_clamp",
    "gate.one_flight.min_inliers", "gate.one_flight.max_iterations",
    "gate.quaternion_norm_range", "gate.coordinate_bound", "gate.ray_cutoff", "gate.mesh_cast", "gate.opaque_forced",
    "caps.files", "caps.megabytes", "caps.geoms_per_flight", "caps.mesh_faces_per_flight",
    "caps.mesh_megabytes_per_flight", "caps.stl_faces_per_file",
    "gate.one_flight.scale_min_spread", "hazard.structure_floor",
    "caps.bodies_per_flight", "caps.xml_elements_per_flight", "caps.mesh_assets_per_flight",
    "contract.megabyte_bytes", "gate.warnings_fail",
    "caps.nesting_levels_per_flight", "runtime.rays_time_limit_s",
    "runtime.scene_time_limit_s", "runtime.scene_memory_limit_mb",
    "key_frames.named", "flights.frames_given", "score.hazard_aggregation", "score.depth_aggregation",
)
# keys held by rule: {key: (the key whose value decides, the value with which the key must be present)}; with any other
# value of the deciding key the key must be absent (the second version: key_frames.list is not a public entry)
HELD_BY_RULE = {"key_frames.list": ("key_frames.named", True)}
# the registered values of the three aggregations (score.py computes every one; the configuration names the one in force)
FLIGHT_AGGREGATIONS = ("sum", "product")
HAZARD_AGGREGATIONS = ("moves", "min_of_moves_and_poses", "min_of_moves_and_clean_poses")
DEPTH_AGGREGATIONS = ("weighted", "product")
# numbers the grader needs that the table does not hold; they would reach the grader only through
# "pending_in_table". Empty: the two gaps of the first build (the one-flight fit's smallest spread and the floor of
# the hazard term) are public entries of the table now and are read as values.
GAP_KEYS = ()
LAYOUT_KEYS = ("truth_dir", "reference_dir", "givens_dir", "frames_csv", "estimate_csv", "ray_table")
RUNTIME_KEYS = ("worker_account", "worker_address_space_mb", "default_budget_s", "reserve_s", "min_worker_s",
                "max_worker_s", "worker_margin_s", "stage_caps_s", "ray_chunk_rows", "late_gate_max_gap_s")
STAGES = ("selftest", "gate", "scene", "fit", "rays", "hazard", "score")
TOP_KEYS = ("format", "values", "pending_in_table", "layout", "runtime", "generated_from")


class ConfigError(Exception):
    """The configuration is missing a key, holds an unknown key or a value of the wrong kind: a task error."""


def _num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(float(v))


def _nums(v, n=None):
    return isinstance(v, list) and (n is None or len(v) == n) and all(_num(x) for x in v)


def _int(v):
    return isinstance(v, int) and not isinstance(v, bool)


# the kind of every value key (a check of form, not of size: sizes are the table's)
_KIND = {
    "flights.count_first_version": _int,
    "flights.names_neutral": lambda v: isinstance(v, list) and v and all(isinstance(x, str) and x for x in v),
    "key_frames.per_flight": _int,
    "key_frames.list": lambda v: isinstance(v, dict) and all(
        isinstance(k, str) and isinstance(x, list) and all(isinstance(y, str) for y in x) for k, x in v.items()),
    "wide_camera.body_mount_translation": lambda v: _nums(v, 3),
    "wide_camera.body_mount_quaternion_xyzw": lambda v: _nums(v, 4),
    "two_camera_transform.translation": lambda v: _nums(v, 3),
    "two_camera_transform.quaternion_xyzw": lambda v: _nums(v, 4),
    "depth_camera.image_size": lambda v: isinstance(v, list) and len(v) == 2 and all(_int(x) and x > 0 for x in v),
    "depth_camera.rays": _int, "depth_camera.never_returning_corner_pixels": _int,
    "depth_camera.ray_table_sha256": lambda v: isinstance(v, str) and len(v) == 64,
    "depth.min_class_pixels_per_frame": _int, "hazard.inflation_offsets": _int,
    "hazard.move_start": lambda v: _nums(v, 3), "hazard.directions_azimuth": lambda v: _nums(v) and len(v) > 0,
    "hazard.directions_elevation": lambda v: _nums(v) and len(v) > 0, "hazard.lengths": lambda v: _nums(v) and len(v) > 0,
    "score.flight_aggregation": lambda v: v in FLIGHT_AGGREGATIONS,
    "score.hazard_aggregation": lambda v: v in HAZARD_AGGREGATIONS,
    "score.depth_aggregation": lambda v: v in DEPTH_AGGREGATIONS,
    "key_frames.named": lambda v: isinstance(v, bool),
    "flights.frames_given": lambda v: isinstance(v, dict) and len(v) > 0 and all(
        isinstance(k, str) and _int(x) and x > 0 for k, x in v.items()),
    "gate.one_flight.scale_clamp": lambda v: _nums(v, 2), "gate.one_flight.min_inliers": _int,
    "gate.one_flight.max_iterations": _int, "gate.quaternion_norm_range": lambda v: _nums(v, 2),
    "gate.mesh_cast": lambda v: isinstance(v, str), "gate.opaque_forced": lambda v: v is True,
    "caps.files": _int, "caps.geoms_per_flight": _int, "caps.mesh_faces_per_flight": _int,
    "caps.stl_faces_per_file": _int,
    "caps.bodies_per_flight": _int, "caps.xml_elements_per_flight": _int, "caps.mesh_assets_per_flight": _int,
    "contract.megabyte_bytes": lambda v: _int(v) and v > 0, "gate.warnings_fail": lambda v: isinstance(v, bool),
    "caps.nesting_levels_per_flight": lambda v: _int(v) and v > 0,
    "runtime.rays_time_limit_s": lambda v: _num(v) and v > 0,
    "runtime.scene_time_limit_s": lambda v: _num(v) and v > 0,
    "runtime.scene_memory_limit_mb": lambda v: _int(v) and v > 0,
}
_RUNTIME_KIND = {
    "worker_account": lambda v: isinstance(v, str) and v,
    "stage_caps_s": lambda v: isinstance(v, dict) and set(v) == set(STAGES) and all(_num(x) and x > 0 for x in v.values()),
    "ray_chunk_rows": lambda v: _int(v) and v > 0,
}


class Config(dict):
    """The flat mapping of values (VALUE_KEYS and GAP_KEYS); `layout` and `runtime` beside it. `read` records every
    key looked up, so a test can show that each key of the file is read by the grader."""

    def __init__(self, values, layout, runtime, gaps):
        super().__init__(values)
        self.layout = dict(layout)
        self.runtime = dict(runtime)
        self.gaps = dict(gaps)
        self.read = set()

    def __getitem__(self, key):
        self.read.add(key)
        try:
            return dict.__getitem__(self, key)
        except KeyError:
            raise ConfigError("the configuration has no entry %r" % key) from None

    def get(self, key, default=None):             # noqa: D401 - no defaults: get() is refused
        raise ConfigError("the grader reads no configuration key with a default (%r)" % key)


def from_document(doc):
    """A Config from the parsed grader_config.json; ConfigError when anything is missing, extra or of the wrong kind."""
    if not isinstance(doc, dict):
        raise ConfigError("grader_config.json is not an object")
    extra = sorted(set(doc) - set(TOP_KEYS))
    missing = sorted(set(TOP_KEYS) - set(doc) - {"generated_from"})
    if extra or missing:
        raise ConfigError("grader_config.json: unknown sections %s, missing sections %s" % (extra, missing))
    if doc["format"] != FORMAT:
        raise ConfigError("grader_config.json: format %r, expected %r" % (doc["format"], FORMAT))
    vals, gaps, lay, rt = doc["values"], doc["pending_in_table"], doc["layout"], doc["runtime"]
    for name, sec in (("values", vals), ("pending_in_table", gaps), ("layout", lay), ("runtime", rt)):
        if not isinstance(sec, dict):
            raise ConfigError("grader_config.json: %s is not an object" % name)
    if not isinstance(vals.get("key_frames.named"), bool):
        raise ConfigError("grader_config.json values: key_frames.named must be true or false, not %r"
                          % (vals.get("key_frames.named"),))
    held = held_keys(vals)
    for name, sec, keys in (("values", vals, VALUE_KEYS + held), ("layout", lay, LAYOUT_KEYS),
                            ("runtime", rt, RUNTIME_KEYS)):
        miss = [k for k in keys if k not in sec]
        unknown = sorted(set(sec) - set(keys))
        if miss or unknown:
            raise ConfigError("grader_config.json %s: missing %s, not read by the grader %s" % (name, miss, unknown))
    both = sorted(set(gaps) & set(vals))
    unknown = sorted(set(gaps) - set(GAP_KEYS))
    if both or unknown:
        raise ConfigError("pending_in_table: %s also in values, %s not a known gap" % (both, unknown))
    flat = dict(vals)
    for k in GAP_KEYS:
        if k in vals:
            continue
        e = gaps.get(k)
        if not isinstance(e, dict) or "value" not in e:
            raise ConfigError("the configuration has no entry %r (neither in values nor in pending_in_table)" % k)
        flat[k] = e["value"]
    for k in VALUE_KEYS + held + GAP_KEYS:
        kind = _KIND.get(k, _num)
        if not kind(flat[k]):
            raise ConfigError("the configuration entry %r has a value of the wrong kind: %r" % (k, flat[k]))
    for k in LAYOUT_KEYS:
        if not isinstance(lay[k], str) or not lay[k] or lay[k].startswith("/") or ".." in lay[k].split("/"):
            raise ConfigError("layout %r must be a relative path inside the stage" % k)
    for k in RUNTIME_KEYS:
        if not _RUNTIME_KIND.get(k, lambda v: _num(v) and v >= 0)(rt[k]):
            raise ConfigError("runtime %r has a value of the wrong kind: %r" % (k, rt[k]))
    # the ray stage's cap of the runtime block is the printed limit of rule Z7: one number, the table's entry
    if float(rt["stage_caps_s"]["rays"]) != float(flat["runtime.rays_time_limit_s"]):
        raise ConfigError("runtime stage_caps_s rays (%r) is not runtime.rays_time_limit_s (%r)"
                          % (rt["stage_caps_s"]["rays"], flat["runtime.rays_time_limit_s"]))
    # so are the scene stage's cap and the worker's address-space limit (rule Z7's limits on building the ray scene)
    if float(rt["stage_caps_s"]["scene"]) != float(flat["runtime.scene_time_limit_s"]):
        raise ConfigError("runtime stage_caps_s scene (%r) is not runtime.scene_time_limit_s (%r)"
                          % (rt["stage_caps_s"]["scene"], flat["runtime.scene_time_limit_s"]))
    if int(rt["worker_address_space_mb"]) != int(flat["runtime.scene_memory_limit_mb"]):
        raise ConfigError("runtime worker_address_space_mb (%r) is not runtime.scene_memory_limit_mb (%r)"
                          % (rt["worker_address_space_mb"], flat["runtime.scene_memory_limit_mb"]))
    if sorted(flat["flights.frames_given"]) != sorted(flat["flights.names_neutral"]):
        raise ConfigError("flights.frames_given does not name exactly the flights of flights.names_neutral")
    if "key_frames.list" in held and sorted(flat["key_frames.list"]) != sorted(flat["flights.names_neutral"]):
        raise ConfigError("key_frames.list does not name exactly the flights of flights.names_neutral")
    return Config(flat, lay, rt, gaps)


def held_keys(values):
    """The keys held by rule that the values must hold (HELD_BY_RULE), as a tuple; the others must be absent."""
    return tuple(k for k, (by, want) in sorted(HELD_BY_RULE.items()) if values.get(by) is want)


def load(path):
    try:
        with open(path, "rb") as fh:
            doc = json.loads(fh.read().decode("utf-8"))
    except (OSError, ValueError, UnicodeDecodeError) as exc:
        raise ConfigError("grader_config.json cannot be read: %s" % exc) from None
    return from_document(doc)
